      <a href="github.com/sudeshna-22" className="home-social-icon" target='_blank'><i className="uil uil-github-alt"></i></a>
      <a href="instagram.com/sudeshna_ev/" className="home-social-icon" target='_blank' noopener noreferrer><i className="uil uil-instagram"></i></a>
      <a href="facebook.com/shrutii3101/" className="home-social-icon" target='_blank' noopener noreferrer><i className="uil uil-facebook"></i></a>
    </div>
  )
}

export default Social
